import {runActionFlow} from './approved-flow.js';
import {esc,cash,icon} from './ui.js';
import {getCampusGame,getCampusRun} from './learning-game-model.js';
import {bindCampusMotion} from './learning-game-motion.js';
import {getWorldPresentation} from './learning-game-world-content.js';
import {bindLuxWorld} from './learning-game-world-motion.js';
import {getCampusReflection} from './learning-game-reflection.js';
import {renderWorldProp} from './learning-game-world-art.js';

const pendingMotion=new WeakMap(),newChapters=new WeakMap();
const queueMotion=(ctx,value)=>pendingMotion.set(ctx,{direction:'forward',fresh:false,...value});
const queuedMotion=ctx=>pendingMotion.get(ctx)||{direction:'forward',fresh:false};
const systemMotionQuery=()=>{try{return globalThis.matchMedia?.('(prefers-reduced-motion: reduce)');}catch{return null;}};
const motionToggle=ctx=>{const device=systemMotionQuery()?.matches===true,off=ctx.draft?.campusMotionOff===true;return `<button type="button" class="campus-motion-toggle" data-campus-action="motion" aria-pressed="${!device&&!off}" aria-label="${device?'Animations reduced by device settings':`Turn animations ${off?'on':'off'}`}" ${device?'disabled':''}>${icon('spark',15)}<span>${device?'Motion reduced':`Motion ${off?'off':'on'}`}</span></button>`;};
const MAP={section:'learn',page:'game'},REWARDS={section:'learn',page:'rewards'};
const lux='<img src="/assets/lux-chat-2d.webp" width="180" height="180" alt="Lux, your campus run buddy">';
const shortMoney=value=>cash(value,{decimals:false});
const starRow=(value=0)=>`<span class="campus-stars" role="img" aria-label="${value} of 3 skill stars">${Array.from({length:3},(_,i)=>`<span class="${i<value?'earned':''}" data-motion="star" data-motion-index="${i}" aria-hidden="true">${i<value?'★':'☆'}</span>`).join('')}</span>`;
const button=(text,action,{secondary=false,extra='',disabled=false}={})=>`<button type="button" class="button${secondary?' secondary':''}" data-campus-action="${action}" ${extra} ${disabled?'disabled':''}>${text}</button>`;
const textButton=(text,action)=>`<button type="button" class="campus-text-button" data-campus-action="${action}">${text}</button>`;
const error=()=>'<p class="error campus-error" data-campus-error role="alert"></p>';
const foot=html=>`<footer class="campus-footer">${html}</footer>`;
const gameData=ctx=>getCampusGame(ctx.state);
const equippedId=game=>typeof game.equipped==='object'?game.equipped?.id:game.equipped;
function dress(game){const reward=game.rewards?.find(r=>r.id===equippedId(game));return reward&&reward.id!=='classic'?`<span class="campus-equipped" aria-label="Lux look: ${esc(reward.title)}">${esc(reward.emoji)}</span>`:'';}
function buddy(game,{small=false}={}){return `<div class="campus-hero ${small?'small':''}" data-motion="hero"><div class="campus-buddy" data-look="${esc(equippedId(game)||'classic')}"><div class="campus-lux" data-motion="lux">${lux}${dress(game)}</div></div></div>`;}
function detailsButton(){return `<button type="button" class="campus-details-button" data-campus-action="details" aria-label="Game details">${icon('more',21)}</button>`;}
function header(title,{learning=false}={}){return `<header class="campus-header"><button type="button" data-campus-action="${learning?'learning':'map'}" class="campus-back" aria-label="${learning?'Back to Learn with Lux':'Back to campus map'}">${icon('back',18)}<span>${learning?'Learn':'Map'}</span></button><span>${esc(title)}</span><div class="campus-header-actions"><button type="button" data-campus-action="home" class="campus-home" aria-label="Go to Home">${icon('home',18)}</button>${detailsButton()}</div></header>`;}
const frame=(ctx,title,body,{className='',learning=false}={})=>`<section class="page campus-game-page campus-clean ${className} ${ctx.draft?.campusMotionOff?'campus-motion-off':''}">${header(title,{learning})}${body}</section>`;
function nextMission(game){return game.missions?.find(m=>m.id===game.nextMissionId)||game.missions?.find(m=>m.unlocked&&!m.completed)||game.missions?.[0];}
function mainPlay(game){const active=game.activeRunId,mission=nextMission(game);if(active)return button('Resume my run','resume');if(game.allCompleted)return button('Choose a replay','map');return mission?button('Let’s play','start',{extra:`data-mission-id="${esc(mission.id)}"`}):'';}
function storyNumber(value,from=value){return `<span class="campus-sr-only">${shortMoney(value)}</span><span aria-hidden="true" data-motion="number" data-motion-from="${from}" data-motion-to="${value}">${shortMoney(value)}</span>`;}
function walletPill(money={}){const gap=money.shortfall||0;return `<button type="button" class="campus-wallet-pill" data-campus-action="wallet" aria-label="Story money: ${esc(shortMoney(money.wallet))} in wallet, ${esc(shortMoney(gap||money.flexible||0))} ${gap?'needs covering':'room for plans'}. View the full story wallet"><span>Story money</span><strong>${shortMoney(money.wallet)}</strong><span>·</span><span class="${gap?'needs-room':''}">${shortMoney(gap||money.flexible||0)} ${gap?'to cover':'room'}</span>${icon('chevron',13)}</button>`;}
function moneyStrip(money={}){return `<div class="campus-details-wallet"><p class="campus-details-note">Story money · no real payments</p>${[['Story wallet',money.wallet],['Planned costs',money.committed],['Cushion',money.cushion],['Expected · hasn’t arrived',money.expected],[(money.shortfall||0)>0?'Needs covering':'Room for plans',money.shortfall||money.flexible||0]].map(([label,value])=>`<div class="campus-detail-row"><span>${label}</span><strong>${shortMoney(value)}</strong></div>`).join('')}</div>`;}
function routeFor(run){if(run.ending?.route)return run.ending.route;if(run.topicId==='safety')return {section:'learn',page:'lesson',id:'safety-recipient'};return {section:'learn',page:'practice',id:['planning','upcoming','expected'].includes(run.topicId)?'incoming-plan':'weekly-review'};}
function choiceLabel(choice){const amounts=[...new Set(((choice.detail||'').match(/GH₵\d[\d,.]*/g)||[]).map(value=>value.replace(/[.,]+$/,'')))].filter(value=>!choice.label.includes(value));return `${choice.label}${amounts.length?` · ${amounts.join(' / ')}`:''}`;}
function sceneCopy(title,body=''){return `<div class="campus-clean-copy"><h1 data-motion="title">${esc(title)}</h1>${body?`<p data-motion="body">${esc(body)}</p>`:''}</div>`;}

const WORLD_POINTS=[{x:22,y:58},{x:50,y:75},{x:78,y:58}];
const worldPoint=index=>WORLD_POINTS[index]||{x:12,y:94};
const safePoint=point=>point&&Number.isFinite(point.x)&&Number.isFinite(point.y)?{x:Math.max(4,Math.min(96,point.x)),y:Math.max(20,Math.min(96,point.y))}:null;
function selectedChoiceId(run){return run.turn?.choices?.find(choice=>choice.label===run.lastOutcome?.choiceLabel)?.id||'';}
function scenery(){return `<svg class="lux-world-scenery" viewBox="0 0 400 560" preserveAspectRatio="none" aria-hidden="true" focusable="false"><rect class="world-sky" width="400" height="560"/><g class="world-cloud"><path d="M27 65c2-10 16-12 22-4 8-5 20 0 20 8H22c-2-4 1-6 5-4Z"/></g><g class="world-cloud cloud-two"><path d="M284 88c1-11 17-14 24-6 11-6 24-1 24 10h-55c-2-3 1-6 7-4Z"/></g><path class="world-hill" d="M0 262Q90 220 200 258T400 242V560H0Z"/><g class="world-building"><path d="M43 233h132v82H43Zm182 0h132v82H225Z"/><path d="M34 233l75-30 75 30Zm182 0 75-30 75 30Z"/><path d="M176 130h48v185h-48Zm-7 0 31-30 31 30Z"/><path d="M185 315v-36q15-24 30 0v36Z"/><circle class="world-clock" cx="200" cy="164" r="12"/><path class="world-clock-hand" d="M200 155v9l7 4"/></g><g class="world-window"><path d="M58 263q9-18 18 0v24H58Zm39 0q9-18 18 0v24H97Zm39 0q9-18 18 0v24h-18Zm109 0q9-18 18 0v24h-18Zm39 0q9-18 18 0v24h-18Zm39 0q9-18 18 0v24h-18Z"/></g><g class="world-palm"><path d="m25 310 4-103M29 213q-27-24-27-6 15-5 27 6Zm0 0q17-31 34-19-24 5-34 19Zm0 0q-4-34-22-28 18 8 22 28Zm0 0q24-11 31 6-17-7-31-6ZM372 304l-3-91m0 7q-22-25-29-10 18-3 29 10Zm0 0q13-30 29-18-19 4-29 18Zm0 0q22-6 26 9-13-7-26-9Z"/></g><path class="world-ground" d="M0 348Q90 322 200 351T400 342V560H0Z"/></svg>`;}
function worldPlayer(game,point={x:12,y:94},tutorial=false){return `<div class="lux-world-player" data-world-player data-world-x="${point.x}" data-world-y="${point.y}" style="--lux-x:${point.x}%;--lux-y:${point.y}%" tabindex="0" role="button" aria-label="Lux. Drag to a destination, or use arrow keys to move and Space to jump."><span class="lux-world-shadow" aria-hidden="true"></span><div class="lux-world-sprite" data-look="${esc(equippedId(game)||'classic')}" aria-hidden="true"><img src="/assets/lux-chat-2d.webp" width="88" height="88" alt="" draggable="false">${dress(game)}</div><span class="lux-world-feet" aria-hidden="true"><i></i><i></i></span>${tutorial?`<span class="lux-world-drag-cue" aria-hidden="true">${icon('arrow',18)}</span>`:''}</div>`;}
function worldHud(run,ctx){const m=run.money||{},cue=queuedMotion(ctx),before=cue.fresh&&cue.runId===run.id?cue.moneyFrom:null,planned=m.committed||0,oldPlanned=before?before.committed||0:planned,gap=m.shortfall||0;return `<button type="button" class="lux-world-hud" data-campus-action="wallet" aria-label="Story money: wallet ${shortMoney(m.wallet)}, plan ${shortMoney(planned)}, cushion ${shortMoney(m.cushion||0)}, ${gap?'shortfall':'room after plan and cushion'} ${shortMoney(gap||m.flexible||0)}. Open story wallet."><span><i>${icon('card',15)}</i><small>Wallet</small><strong>${storyNumber(m.wallet,before?.wallet??m.wallet)}</strong></span><span><i>${icon('lock',15)}</i><small>Plan</small><strong>${storyNumber(planned,oldPlanned)}</strong></span><span class="${gap?'has-gap':''}"><i>${icon(gap?'info':'spark',15)}</i><small>${gap?'Need':'Room'}</small><strong>${storyNumber(gap||m.flexible||0,before?(before.shortfall||before.flexible||0):(gap||m.flexible||0))}</strong></span></button>`;}
function moneyFeedback(run,ctx){
 const changes=run.lastOutcome?.changes||[],cue=queuedMotion(ctx),fresh=cue.fresh&&cue.runId===run.id;
 if(!changes.length)return '';
 return `<div class="lux-world-money-effects" role="group" aria-label="Changes to story money">${changes.map(change=>{const delta=change.after-change.before,plan=change.label==='Planned costs',label=plan?(delta<0?'Plan released':'Plan reserved'):change.label==='Story wallet'?'Wallet':change.label,amount=shortMoney(Math.abs(delta)),value=plan?amount:`${delta>0?'+':'−'}${amount}`;return `<span class="lux-world-coin" ${fresh?'data-world-effect':''}><small>${esc(label)}</small><strong>${esc(value)}</strong></span>`;}).join('')}</div>`;
}
function worldStage(run,game,ctx,{preview=false,completed=false}={}){
 const view=run?getWorldPresentation(run):{world:'campus',prompt:'Your campus. Your move.',targets:[],facts:[]},phase=preview?'preview':completed?'completed':run.status,targets=view.targets||[],chosen=run?selectedChoiceId(run):'',selectedIndex=targets.findIndex(target=>target.id===chosen),cue=queuedMotion(ctx),fresh=run&&cue.fresh&&cue.runId===run.id,point=safePoint(fresh?cue.from:null)||(completed?{x:50,y:68}:phase==='consequence'&&selectedIndex>=0?worldPoint(selectedIndex):preview?{x:28,y:83}:{x:12,y:94});
 const prompt=preview?'Your campus. Your move.':completed?'Chapter explored!':phase==='consequence'?view.outcome?.line||'You found a route.':view.prompt;
 const firstFacts=phase==='choice'?(view.facts||[]):[],arrival=phase==='choice'&&view.arrival;
 const controlsLearned=ctx.draft?.campusDragHintSeen===true||game.completedCount>0||(run?.turnIndex||0)>0||!!run?.lastOutcome;
 const tutorial=phase==='choice'&&!controlsLearned;
 return `<div class="lux-world-stage ${preview?'is-preview':''}" data-world-stage data-world="${esc(view.world||'campus')}" data-phase="${phase}" data-world-tutorial="${tutorial}" role="region" aria-label="Campus Run play area">${scenery()}<div class="lux-world-floor" aria-hidden="true"></div><svg class="lux-world-path" viewBox="0 0 100 100" preserveAspectRatio="none" aria-hidden="true"><path d="M12 94Q12 65 22 58M12 94Q30 83 50 75M12 94Q48 82 78 58"/></svg><div class="lux-world-speech" aria-live="polite"><h1>${esc(prompt)}</h1>${phase==='consequence'&&selectedIndex>=0?`<small class="lux-world-selected-choice">${esc(targets[selectedIndex].label)}</small>`:''}</div>${firstFacts.length?`<div class="lux-world-facts">${firstFacts.slice(0,2).map(f=>`<span>${esc(f.label)} <b>${esc(f.value)}</b></span>`).join('')}</div>`:''}${arrival?`<span class="lux-world-arrival" aria-label="${esc(arrival.label)}">${icon('check',12)} ${esc(arrival.label)}</span>`:''}${phase==='choice'&&(run.money.expected||0)>0?`<button type="button" class="lux-world-expected" data-campus-action="wallet" aria-label="${esc(shortMoney(run.money.expected))} expected, not available"><span aria-hidden="true">☁</span><small>${shortMoney(run.money.expected)}<br>expected</small></button>`:''}${!preview&&!completed?targets.map((target,index)=>{const pos=worldPoint(index),active=phase==='choice';return `<button type="button" class="lux-world-target ${target.id===chosen?'is-selected':''}" style="--target-x:${[22,50,78][index]}%;--target-y:${[38,55,38][index]}%" data-world-choice="${esc(target.id)}" data-world-destination="${esc(target.id)}" data-world-x="${pos.x}" data-world-y="${pos.y}" data-campus-choice="${esc(target.id)}" ${active?'':`disabled tabindex="-1" aria-hidden="true"`} aria-label="${esc(`${target.label}${target.costLabel?`. ${target.costLabel}`:''}. ${run.turn.choices.find(c=>c.id===target.id)?.detail||''}`)}"><span class="lux-world-target-art" aria-hidden="true">${renderWorldProp(target)}</span><span class="lux-world-target-label">${esc(target.label)}</span>${target.costLabel?`<span class="lux-world-target-cost">${esc(target.costLabel)}</span>`:''}<span class="lux-world-target-base" aria-hidden="true"></span></button>`;}).join(''):''}${completed?`<div class="lux-world-podium" aria-hidden="true"></div><div class="lux-world-finish-stars">${starRow(run.stars||0)}</div>`:''}${worldPlayer(game,point,tutorial)}${!preview&&phase==='consequence'?`<button type="button" class="lux-world-gate" data-world-gate data-world-x="88" data-world-y="84" data-campus-action="continue" aria-label="${run.turnIndex>=run.turnCount-1?'See my ending':'See what’s next'}"><span class="lux-world-gate-art" aria-hidden="true">${icon('arrow',25)}</span><span>${run.turnIndex>=run.turnCount-1?'Finish':'Next'}</span></button><button type="button" class="lux-world-rewind" data-campus-action="rewind" aria-label="Try another move">${icon('repeat',18)}</button>`:''}${completed?`<button type="button" class="lux-world-gate" data-world-gate data-world-x="88" data-world-y="84" data-campus-action="${run.nextMissionId?'next':'map'}" ${run.nextMissionId?`data-mission-id="${esc(run.nextMissionId)}"`:''} aria-label="${run.nextMissionId?'Next chapter':'Back to campus map'}"><span class="lux-world-gate-art" aria-hidden="true">${icon('arrow',25)}</span><span>${run.nextMissionId?'Next chapter':'Campus map'}</span></button>`:''}${phase==='choice'?`<span class="lux-world-instruction" data-world-instruction>${tutorial?'<strong>Drag Lux to a place.</strong><span>Or tap a choice.</span>':'Tap a place. Or move Lux.'}</span>`:''}</div>`;
}
export function renderCampusGameEntry(ctx){
 const game=gameData(ctx),mission=nextMission(game),done=game.allCompleted;
 return `<section class="campus-game-entry lux-world-entry ${ctx.draft?.campusMotionOff?'campus-motion-off':''}"><div class="campus-entry-top"><span>Campus Run</span>${detailsButton()}</div>${game.recoveryNotice?`<p class="campus-notice">${esc(game.recoveryNotice)}</p>`:''}${worldStage(null,game,ctx,{preview:true})}<p class="lux-world-entry-mission">${esc(done?'Campus complete':game.activeRunId?'Your run is saved':mission?.title||'Your next move')}</p>${mainPlay(game)}<div class="campus-entry-links">${textButton('Campus map','map')}${textButton('Lux looks','rewards')}</div><p class="campus-clean-fine">Story money</p>${error()}</section>`;
}

function map(ctx){
 const game=gameData(ctx),next=game.allCompleted?null:nextMission(game),chapter=game.missions.find(m=>m.id===newChapters.get(ctx)),points=[{x:23,y:85},{x:75,y:70},{x:25,y:55},{x:75,y:40},{x:25,y:25},{x:72,y:10}],current=points[next?.index??5];
 return frame(ctx,'Campus map',`<h1 class="campus-sr-only">Campus map</h1><div class="lux-world-map-score"><span>★ ${game.totalStars}/${game.maxStars}</span>${game.activeRunId?textButton('Resume my run','resume'):''}${textButton('Lux looks','rewards')}</div>${game.recoveryNotice?`<p class="campus-notice">${esc(game.recoveryNotice)}</p>`:''}${chapter?`<p class="campus-chapter-unlock" data-motion="unlock">${esc(chapter.title)} is open.</p>`:''}<div class="lux-world-map-stage" data-world="campus" aria-label="Campus mission map">${scenery()}<svg class="lux-world-map-road" viewBox="0 0 100 100" preserveAspectRatio="none" aria-hidden="true"><path d="M23 85C23 75 75 80 75 70S25 65 25 55 75 50 75 40 25 35 25 25 72 20 72 10"/></svg>${game.missions.map((m,index)=>`<button type="button" class="lux-world-level-node ${m.completed?'complete':m.unlocked?'open':'locked'} ${m.id===next?.id?'next':''} ${m.id===chapter?.id?'newly-unlocked':''}" style="--node-x:${points[index].x}%;--node-y:${points[index].y}%" data-campus-mission="${esc(m.id)}" ${!m.unlocked?'disabled':''} aria-label="${esc(`${m.title}. ${m.completed?`${m.bestStars} of 3 skill stars. Replay`:m.unlocked?'Ready to play':'Complete the previous chapter to unlock'}`)}"><span class="lux-world-level-number">${m.unlocked?index+1:icon('lock',18)}</span><span class="lux-world-level-label">${esc(m.title)}</span>${m.completed?starRow(m.bestStars):''}</button>`).join('')}<img class="lux-world-map-lux" style="--node-x:${current.x}%;--node-y:${current.y}%" src="/assets/lux-chat-2d.webp" alt="Lux is ready for the next chapter" width="52" height="52"></div>${error()}`,{className:'campus-map lux-world-map',learning:true});
}

function choiceScreen(ctx,run,game){return frame(ctx,`${run.turnIndex+1} / ${run.turnCount||3}`,`${worldHud(run,ctx)}${worldStage(run,game,ctx)}${error()}`,{className:'campus-play lux-world-page lux-world-choice'});}
function consequenceScreen(ctx,run,game){return frame(ctx,`${run.turnIndex+1} / ${run.turnCount||3}`,`${worldHud(run,ctx)}${moneyFeedback(run,ctx)}${worldStage(run,game,ctx)}${error()}`,{className:'campus-play lux-world-page lux-world-consequence'});}
const reflectionStep=r=>['lesson','insight'].includes(r?.step)?r.step:'';
function reflectionHeader(step){const back=step==='insight'?'reflection-lesson':step==='lesson'?'reflection-result':'map',label=step==='insight'?'Back to lesson':step==='lesson'?'Back to chapter result':'Back to campus map';return `<header class="campus-header"><button type="button" data-campus-action="${back}" class="campus-back" aria-label="${label}">${icon('back',18)}<span>${step==='insight'?'Lesson':step==='lesson'?'Run':'Map'}</span></button><span>${step==='insight'?'Your insight':step==='lesson'?'Take it with you':'Chapter complete'}</span><div class="campus-header-actions"><button type="button" data-campus-action="home" class="campus-home" aria-label="Go to Home">${icon('home',18)}</button>${detailsButton()}</div></header>`;}
function reflectionHero(game){return `<div class="reflection-hero" data-motion="hero"><span class="reflection-hero-halo" aria-hidden="true"></span><div class="reflection-lux" data-look="${esc(equippedId(game)||'classic')}" data-motion="lux">${lux}${dress(game)}</div></div>`;}
function reflectionProgress(step){return `<div class="reflection-progress" aria-label="Chapter takeaways"><span class="${step==='lesson'?'is-current':'is-complete'}" ${step==='lesson'?'aria-current="step"':''}><span class="campus-sr-only">Lesson</span></span><span class="${step==='insight'?'is-current':''}" ${step==='insight'?'aria-current="step"':''}><span class="campus-sr-only">Your insight</span></span></div>`;}
function reflectionFrame(ctx,step,body,footer,{result=false}={}){return `<section class="page campus-game-page campus-clean campus-reflection-page ${result?'campus-chapter-result':''} ${ctx.draft?.campusMotionOff?'campus-motion-off':''}" data-reflection-step="${step||'result'}">${reflectionHeader(step)}${step?reflectionProgress(step):''}<div class="reflection-body">${body}</div><footer class="reflection-footer">${footer}</footer>${error()}</section>`;}
function continueLabel(ctx,run,game,{skip=false}={}){if(game.activeRunId)return 'Resume my run';if(ctx.route?.archived||!run.nextMissionId||game.missions.find(m=>m.id===run.nextMissionId)?.completed)return 'Back to campus map';return skip?'Keep playing':'Next chapter';}
function keepPlayingButton(ctx,run,game){return textButton(continueLabel(ctx,run,game,{skip:true}),'reflection-keep-playing');}
function lessonVisual(visual={}){const itemIcons={Plan:'plan',Cushion:'lock',Room:'spark',Printing:'plan',Binding:'box',Trip:'arrow',Approved:'users',Processing:'repeat',Confirmed:'check','Official receipt':'plan','Same screenshot':'repeat',Essentials:'home','Optional order':'calendar','Saving rule':'box'};return `<div class="reflection-visual" data-lesson-kind="${esc(visual.kind||'split')}" aria-label="${esc(visual.caption||'Lesson example')}">${(visual.items||[]).map((item,index)=>`<div class="reflection-chip" data-value="${Number.isSafeInteger(item.amount)?'money':'status'}" data-motion="choice" data-motion-index="${index}"><span class="reflection-chip-art" aria-hidden="true">${icon(itemIcons[item.label]||(visual.kind==='pace'?'calendar':'spark'),24)}</span><small>${esc(item.label)}</small>${Number.isSafeInteger(item.amount)?`<strong>${shortMoney(item.amount)}</strong>${item.status?`<span class="reflection-chip-status">${esc(item.status)}</span>`:''}`:item.status?`<strong>${esc(item.status)}</strong>`:''}</div>`).join('')}${visual.caption?`<p class="reflection-caption">${esc(visual.caption)}</p>`:''}</div>`;}
function insightMetric(metric){if(!metric)return '';const format=v=>metric.unit==='money'?shortMoney(v):String(v),pair=Number.isFinite(metric.before)&&Number.isFinite(metric.after);return `<div class="reflection-visual reflection-metric"><span class="reflection-metric-label">${esc(metric.label)}</span>${pair?`<div class="reflection-metric-values"><span class="reflection-metric-before"><small>Before</small><strong>${esc(format(metric.before))}</strong></span><span aria-hidden="true">${icon('arrow',23)}</span><span class="reflection-metric-after"><small>After</small><strong>${esc(format(metric.after))}</strong></span></div>`:`<div class="reflection-metric-single"><strong>${esc(format(metric.value??0))}</strong></div>`}</div>`;}
function completionScreen(ctx,run,game){return reflectionFrame(ctx,'',`${reflectionHero(game)}<div class="reflection-copy"><p class="reflection-eyebrow">${esc(run.title)}</p><h1 data-motion="title">Chapter explored.</h1><p class="reflection-challenge-count" data-motion="body">${run.turnCount||3} challenges. A little more clarity.</p></div><div class="reflection-result-stars">${starRow(run.stars||0)}</div>${(run.newRewards||[]).length?`<button type="button" class="lux-world-new-look" data-campus-action="rewards">New Lux look ${icon('arrow',14)}</button>`:''}<p class="reflection-story-label">Story skills · no cash value</p>`,`${button('See what I learned','reflection-lesson')}<div class="reflection-secondary-row">${keepPlayingButton(ctx,run,game)}</div>`,{result:true});}
function reflectionScreen(ctx,run,game,step){const reflection=getCampusReflection(run);if(!reflection)return completionScreen(ctx,run,game);const lesson=step==='lesson',copy=lesson?reflection.lesson:reflection.insight;return reflectionFrame(ctx,step,`${reflectionHero(game)}<div class="reflection-copy"><p class="reflection-eyebrow">${lesson?'The lesson':'Lux noticed · this run'}</p><h1 data-motion="title">${esc(copy.title)}</h1><p data-motion="body">${esc(copy.line)}</p></div>${lesson?lessonVisual(copy.visual):insightMetric(copy.metric)}<p class="reflection-story-label">${esc(reflection.storyLabel)}</p>`,lesson?`${button('See my insight','reflection-insight')}<div class="reflection-secondary-row">${keepPlayingButton(ctx,run,game)}</div>`:`${button(continueLabel(ctx,run,game),'reflection-keep-playing')}<div class="reflection-secondary-row">${textButton(copy.routeLabel||'Try this in Lumo','real-life')}</div>`);}

function play(ctx,r){const game=gameData(ctx),run=getCampusRun(ctx.state,r.id||game.activeRunId);if(!run)return frame(ctx,'Campus Run',`<div class="campus-missing">${buddy(game)}${sceneCopy('Find your next chapter.','Your progress is saved on the map.')}${button('To the campus map','map')}</div>`,{className:'campus-play'});return run.status==='completed'?(reflectionStep(r)?reflectionScreen(ctx,run,game,reflectionStep(r)):completionScreen(ctx,run,game)):run.status==='consequence'?consequenceScreen(ctx,run,game):choiceScreen(ctx,run,game);}
function rewards(ctx){const game=gameData(ctx);return frame(ctx,'Lux looks',`<div class="campus-rewards-hero">${buddy(game)}${sceneCopy('Make Lux your own.')}<p class="campus-map-summary">${game.totalStars}/${game.maxStars} ★</p></div><div class="campus-reward-grid">${game.rewards.map((reward,index)=>`<button type="button" data-motion="choice" data-motion-index="${index}" class="campus-reward ${reward.unlocked?'unlocked':'locked'} ${reward.equipped?'equipped':''}" data-campus-reward="${esc(reward.id)}" ${!reward.unlocked?'disabled':''} aria-label="${esc(`${reward.title}. ${reward.equipped?'Equipped':reward.unlocked?'Equip this Lux look':`Unlocks at ${reward.threshold} skill stars`}`)}"><span class="campus-reward-art" data-look="${esc(reward.id)}" aria-hidden="true">${reward.unlocked?`${lux}<i>${reward.id!=='classic'?esc(reward.emoji):''}</i>`:icon('lock',27)}</span><strong>${esc(reward.title)}</strong><small>${reward.equipped?'Wearing it':reward.unlocked?'Wear this look':`${reward.threshold} ★`}</small></button>`).join('')}</div>${error()}`,{className:'campus-rewards'});}

function detailsContent(ctx,run,game,mode){
 const t=run?.turn,o=run?.lastOutcome,ending=run?.ending;
 const wallet=run?`${moneyStrip(run.money)}`:'';
 const context=run?.status==='choice'?`<section><h3>${esc(t.title)}</h3><p>${esc(t.body)}</p>${t.lux?`<p class="campus-details-tip">Lux: ${esc(t.lux)}</p>`:''}<ul class="campus-choice-notes">${t.choices.map(c=>`<li><strong>${esc(c.label)}</strong><span>${esc(c.detail)}</span></li>`).join('')}</ul></section>`:'';
 const outcome=run?.status==='consequence'?`<section><h3>${esc(o.title)}</h3><p>${esc(o.body)}</p>${o.changes?.length?`<div class="campus-details-changes">${o.changes.map(c=>`<div class="campus-detail-row"><span>${esc(c.label)}</span><strong>${shortMoney(c.before)} → ${shortMoney(c.after)}</strong></div>`).join('')}</div>`:''}${o.skill?`<p class="campus-details-tip">Skill spotted: ${esc(o.skillLabel||'A clear next move')}</p>`:''}</section>`:'';
 const completion=ending?`<section><h3>${esc(ending.title)}</h3><p>${esc(ending.body)}</p><div class="campus-detail-row"><span>This run</span><strong>${run.stars} / 3 ★</strong></div><div class="campus-detail-row"><span>Best run</span><strong>${run.bestStars||run.stars||0} / 3 ★</strong></div><h3>What earned these stars?</h3><ul class="campus-skill-notes">${(ending.skills||[]).map(skill=>`<li>${skill.earned?'★':'☆'} ${esc(skill.label)}</li>`).join('')}</ul><p>Stars recognise the skills in this story. A larger wallet does not earn extra stars.</p></section>`:'';
 if(mode==='wallet')return `<div class="campus-details-sheet"><h2>Story wallet</h2>${wallet}<p class="campus-details-note">Expected money stays separate until a confirmed result arrives.</p></div>`;
 if(mode==='result')return `<div class="campus-details-sheet"><h2>What changed</h2>${outcome}<details><summary>Story wallet</summary>${wallet}</details></div>`;
 if(mode==='reflections'){const saved=[...(ctx.state.learning?.game?.runs||[])].reverse(),completed=game.missions.map(m=>saved.find(v=>v.missionId===m.id&&v.status==='completed')).filter(Boolean).map(v=>getCampusRun(ctx.state,v.id)).filter(Boolean);return `<div class="campus-details-sheet campus-reflection-archive"><h2>Lessons & insights</h2><p class="campus-details-note">${completed.length?'Your latest completed run in each chapter.':'Finish three challenges to unlock your first takeaway.'}</p><div class="campus-reflection-archive-list">${completed.map(v=>`<button type="button" data-campus-reflection-run="${esc(v.id)}"><div><strong>${esc(v.title)}</strong><small>Lesson + your run insight</small></div>${icon('arrow',19)}</button>`).join('')}</div></div>`;}
 const progress=`<p class="campus-details-progress">${game.totalStars} / ${game.maxStars} ★ · ${game.completedCount} / ${game.missions.length} chapters</p>`;
 const explanation=context+outcome+completion;
 const about=`<details class="campus-moment-details"><summary>${run?'About this moment':'About Campus Run'} ${icon('chevron',15)}</summary>${explanation}<p>All game money is fictional. Stars unlock Lux looks and have no cash value. Lessons and practice build your private learning level.</p></details>`;
 return `<div class="campus-details-sheet"><h2>Game details</h2>${progress}${about}<div class="campus-details-actions">${run?textButton('Story wallet','wallet'):''}${ending?textButton('Lesson & insight','reflection-lesson')+textButton('Try a different route','replay')+textButton(ending.routeLabel||'Try this in my life','real-life'):''}${textButton('Lessons & insights','reflections')}${textButton('Campus map','map')}${textButton('Lux looks','rewards')}${textButton('My learning progress','progress')}${textButton('Learning preferences','preferences')}</div><div class="campus-details-motion">${motionToggle(ctx)}</div></div>`;

}

export function renderCampusGame(ctx,r=ctx.route){return r.page==='rewards'?rewards(ctx):r.page==='play'?play(ctx,r):map(ctx);}
function bind(ctx,r,selector){
 const root=ctx.$(selector);if(!root)return ()=>{};
 const runAtBind=r.page==='play'?getCampusRun(ctx.state,r.id):null;
 const kind=selector==='.campus-game-entry'?'entry':r.page==='rewards'?'rewards':r.page==='game'?'map':runAtBind?.status==='completed'?(reflectionStep(r)||'completion'):runAtBind?.status||'choice';
 const queued=pendingMotion.get(ctx),transition=queued&&(!queued.runId||queued.runId===runAtBind?.id)&&(!queued.kind||queued.kind===kind)?queued:{direction:'forward',fresh:false};pendingMotion.delete(ctx);
 const freshChapter=kind==='map'&&!!newChapters.get(ctx);if(kind==='map')newChapters.delete(ctx);
 const motion={...transition,fresh:transition.fresh===true||freshChapter};
 root.setAttribute?.('data-motion-kind',kind);root.setAttribute?.('data-motion-direction',motion.direction||'forward');root.setAttribute?.('data-motion-fresh',String(motion.fresh===true));
 const preferenceQuery=systemMotionQuery(),sheetCleanups=[];
 const updateToggleRoot=target=>{const device=preferenceQuery?.matches===true,off=ctx.draft?.campusMotionOff===true;for(const toggle of target.querySelectorAll?.('.campus-motion-toggle')||[]){toggle.disabled=device;toggle.setAttribute?.('aria-pressed',String(!device&&!off));toggle.setAttribute?.('aria-label',device?'Animations reduced by device settings':`Turn animations ${off?'on':'off'}`);const label=toggle.querySelector?.('span');if(label)label.textContent=device?'Motion reduced':`Motion ${off?'off':'on'}`;}};
 const updateToggles=()=>updateToggleRoot(root);
 if(preferenceQuery?.addEventListener)preferenceQuery.addEventListener('change',updateToggles);else preferenceQuery?.addListener?.(updateToggles);
 const trail=root.querySelector?.('.campus-trail');if(trail?.querySelector&&trail.style?.setProperty){const first=trail.querySelector('.campus-path-dot'),last=trail.querySelector('.campus-stop.next .campus-path-dot')||[...(trail.querySelectorAll?.('.campus-stop.complete .campus-path-dot')||[])].at(-1);if(first?.getBoundingClientRect&&last?.getBoundingClientRect){const start=first.getBoundingClientRect(),finish=last.getBoundingClientRect();trail.style.setProperty('--campus-trace-height',`${Math.max(0,finish.top+finish.height/2-start.top-start.height/2)}px`);}}
 const disposeMotion=bindCampusMotion(root,{kind,reduced:ctx.draft?.campusMotionOff===true,transition:motion,particles:false,celebrate:false});
 if(selector==='.campus-game-page'){const heading=root.querySelector?.('h1');heading?.setAttribute?.('tabindex','-1');heading?.focus?.({preventScroll:true});}
 let alive=true,busy=false,worldController=null;const submitted=new Set();
 const valid=()=>alive&&root.isConnected&&ctx.route.section==='learn';
 const showError=message=>{const target=root.querySelector?.('[data-campus-error]')||ctx.$('[data-campus-error]');if(target)target.textContent=message;else ctx.toast?.(message);};
 const go=(next,direction='forward')=>{queueMotion(ctx,{direction,kind:next.page==='game'?'map':next.page==='rewards'?'rewards':next.page==='home'?'entry':reflectionStep(next)||undefined});ctx.saveDraft?.();ctx.go(next);};
 const act= (type,payload,onSuccess)=>{return runActionFlow(function*(){if(!valid()||busy)return;const key=JSON.stringify([type,payload]);if(submitted.has(key))return;busy=true;submitted.add(key);try{const result=(yield (ctx.actAsync||ctx.act).call(ctx,type,payload));if(!result.ok){submitted.delete(key);showError(result.message||'Let’s pick that move up again.');return;}onSuccess?.(result);}finally{busy=false;}});};
 const start= (missionId,replay=false)=>runActionFlow(function*(){return (yield act('campusStart',{missionId,...(replay?{replay:true}:{})},result=>{queueMotion(ctx,{direction:'forward',kind:'choice',runId:result.runId});ctx.saveDraft?.();ctx.go({section:'learn',page:'play',id:result.runId});}));});
 const openDetails=mode=>{if(!ctx.sheet)return;for(const cleanup of sheetCleanups.splice(0))cleanup();const game=gameData(ctx),run=getCampusRun(ctx.state,r.id||game.activeRunId);ctx.sheet(detailsContent(ctx,run,game,mode),el=>{updateToggleRoot(el);const onPreference=()=>updateToggleRoot(el);if(preferenceQuery?.addEventListener)preferenceQuery.addEventListener('change',onPreference);else preferenceQuery?.addListener?.(onPreference);const handler= e=>{return runActionFlow(function*(){const b=e.target.closest('button');if(!b||b.disabled||!valid()||el.isConnected===false)return;ctx.closeSheet?.();for(const cleanup of sheetCleanups.splice(0))cleanup();(yield handleButton(b));});};el.addEventListener('click',handler);sheetCleanups.push(()=>{el.removeEventListener?.('click',handler);if(preferenceQuery?.removeEventListener)preferenceQuery.removeEventListener('change',onPreference);else preferenceQuery?.removeListener?.(onPreference);});});};
 const acknowledgeControls=()=>{if(!valid()||runAtBind?.status!=='choice'||ctx.draft.campusDragHintSeen===true)return;ctx.draft.campusDragHintSeen=true;const stage=root.querySelector?.('[data-world-stage]');stage?.setAttribute?.('data-world-tutorial','false');const instruction=root.querySelector?.('[data-world-instruction]');if(instruction)instruction.textContent='Tap a place. Or move Lux.';ctx.saveDraft?.();};
 const chooseDestination= choiceId=>{return runActionFlow(function*(){if(!valid())return;const run=getCampusRun(ctx.state,r.id||gameData(ctx).activeRunId);if(!run||run.status!=='choice')return;const from=safePoint(worldController?.getPosition?.())||{x:12,y:94};(yield act('campusChoose',{runId:run.id,stepId:run.stepId,choiceId},result=>{acknowledgeControls();queueMotion(ctx,{kind:'consequence',runId:run.id,fresh:!result.duplicate,choiceId,from,moneyFrom:run.money});ctx.refresh({scroll:0});}));});};
 const handleButton= b=>{return runActionFlow(function*(){
  if(!b||b.disabled||!valid())return;
  const game=gameData(ctx),run=getCampusRun(ctx.state,r.id||game.activeRunId),action=b.dataset.campusAction;
  if(['details','wallet','result','reflections'].includes(action)){openDetails(action);return;}
  if(b.dataset.campusReflectionRun){const completed=getCampusRun(ctx.state,b.dataset.campusReflectionRun);if(completed?.status==='completed')go({section:'learn',page:'play',id:completed.id,step:'lesson',archived:true});return;}
  if(action==='motion'){if(preferenceQuery?.matches===true)return;worldController?.dispose?.();disposeMotion();pendingMotion.delete(ctx);ctx.draft.campusMotionOff=ctx.draft.campusMotionOff!==true;ctx.saveDraft?.();ctx.refresh({scroll:0});return;}
  if(b.dataset.campusMission){const m=game.missions.find(m=>m.id===b.dataset.campusMission);if(m?.unlocked)(yield start(m.id,m.completed));return;}
  if(b.dataset.campusReward){const reward=game.rewards.find(x=>x.id===b.dataset.campusReward);if(!reward?.unlocked||reward.equipped)return;(yield act('campusEquip',{rewardId:reward.id},result=>{queueMotion(ctx,{kind:'rewards',fresh:!result.duplicate});ctx.toast?.('Lux is wearing the new look.');ctx.refresh({scroll:0});}));return;}
  if(b.dataset.campusChoice||b.dataset.worldChoice){(yield chooseDestination(b.dataset.campusChoice||b.dataset.worldChoice));return;}
  if(!action)return;
  if(action==='home'){pendingMotion.delete(ctx);ctx.saveDraft?.();ctx.go({section:'home',page:'home'});return;}
  if(action==='learning'){go({section:'learn',page:'home'},'back');return;}
  if(action==='map'){go(MAP,'back');return;}
  if(action==='rewards'){go(REWARDS);return;}
  if(action==='progress'||action==='preferences'){pendingMotion.delete(ctx);ctx.saveDraft?.();ctx.go({section:'learn',page:action==='progress'?'progress':'preferences',returnTo:{...ctx.route}});return;}
  if(action==='resume'){if(game.activeRunId)go({section:'learn',page:'play',id:game.activeRunId});return;}
  if(['reflection-lesson','reflection-insight','reflection-result'].includes(action)){if(run?.status==='completed'){const step=action==='reflection-lesson'?'lesson':action==='reflection-insight'?'insight':'';go({section:'learn',page:'play',id:run.id,...(step?{step}:{}),...(r.archived?{archived:true}:{})},action==='reflection-result'||r.step==='insight'&&step==='lesson'?'back':'forward');}return;}
  if(action==='reflection-keep-playing'){if(run?.status!=='completed')return;if(game.activeRunId){go({section:'learn',page:'play',id:game.activeRunId});return;}const mission=game.missions.find(m=>m.id===run.nextMissionId);if(!r.archived&&mission?.unlocked&&!mission.completed)(yield start(mission.id));else go(MAP);return;}
  if(action==='start'||action==='next'){const m=game.missions.find(m=>m.id===(b.dataset.missionId||game.nextMissionId));if(m?.unlocked)(yield start(m.id,m.completed));return;}
  if(action==='replay'){if(run)(yield start(run.missionId,true));return;}
  if(action==='real-life'){if(run){pendingMotion.delete(ctx);const next=routeFor(run);ctx.saveDraft?.();ctx.go({...next,returnTo:{section:'learn',page:'play',id:run.id,...(reflectionStep(r)?{step:reflectionStep(r)}:{}),...(r.archived?{archived:true}:{})}});}return;}
  if((action==='continue'||action==='rewind')&&run?.status==='consequence'){(yield act(action==='continue'?'campusContinue':'campusRewind',{runId:run.id,stepId:run.stepId},result=>{const next=getCampusRun(ctx.state,run.id),completed=next?.status==='completed';if(completed&&!result.duplicate&&next.nextMissionId){const before=game.missions.find(m=>m.id===next.nextMissionId),after=gameData(ctx).missions.find(m=>m.id===next.nextMissionId);if(before&&!before.unlocked&&after?.unlocked)newChapters.set(ctx,next.nextMissionId);}queueMotion(ctx,{kind:completed?'completion':'choice',runId:run.id,direction:action==='rewind'?'rewind':'forward',fresh:!result.duplicate,moneyFrom:run.money});ctx.refresh({scroll:0});}));}
 });};
 const click= e=>runActionFlow(function*(){return (yield handleButton(e.target.closest('button')));});
 root.addEventListener('click',click);
 worldController=bindLuxWorld(root,{onChoose:chooseDestination,onInteract:acknowledgeControls,reduced:ctx.draft?.campusMotionOff===true});
 if(kind==='consequence'&&transition.fresh&&transition.choiceId){const destination=[...(root.querySelectorAll?.('[data-world-destination]')||[])].find(el=>el.dataset?.worldDestination===transition.choiceId);const from=safePoint(transition.from);if(from)worldController?.setPosition?.(from);if(destination)worldController?.travelTo?.(destination);}
 return ()=>{alive=false;worldController?.dispose?.();disposeMotion();for(const cleanup of sheetCleanups)cleanup();if(preferenceQuery?.removeEventListener)preferenceQuery.removeEventListener('change',updateToggles);else preferenceQuery?.removeListener?.(updateToggles);root.removeEventListener('click',click);};
}
export const bindCampusGame=(ctx,r=ctx.route)=>bind(ctx,r,'.campus-game-page');
export const bindCampusGameEntry=ctx=>bind(ctx,ctx.route,'.campus-game-entry');
